"use server";

import { createAdminClient } from "@/lib/supabase/admin";
import { createServerClient } from "@/lib/supabase/server";
import { UserRole } from "@/types/database.types";
import { revalidatePath } from "next/cache";

export interface ManagementActionState {
  error?: string;
  success?: boolean;
}

/**
 * Ensures the caller has the required role (ADMIN or COUNSELOR)
 */
async function requireRole(allowedRoles: UserRole[]) {
  const supabase = await createServerClient();
  const { data: { user }, error: authError } = await supabase.auth.getUser();
  if (authError || !user) throw new Error("Unauthorized");

  const { data: profile, error: profileError } = await supabase
    .from("profiles")
    .select("role")
    .eq("id", user.id)
    .single();

  if (profileError || !profile) throw new Error("Unauthorized");

  const role = profile.role as UserRole;
  if (!allowedRoles.includes(role)) {
    throw new Error("Forbidden: Insufficient privileges");
  }

  return { userId: user.id, role };
}

/**
 * Generates a random secure password for newly created accounts.
 * In a real app this would trigger a password reset/invite flow.
 */
function generateTempPassword() {
  return "Password123!"; // Fixed for hackathon demo purposes based on requirements
}

function generateCaseRef() {
  return `V-${Math.floor(1000 + Math.random() * 9000)}`; 
}

export async function createCounselorAction(
  _prevState: ManagementActionState | undefined,
  formData: FormData
): Promise<ManagementActionState> {
  try {
    await requireRole(["ADMIN"]);

    const email = formData.get("email")?.toString().trim();
    const displayName = formData.get("displayName")?.toString().trim();

    if (!email || !displayName) {
      return { error: "Email and Name are required" };
    }

    const adminAuth = createAdminClient().auth.admin;
    const { error: createError } = await adminAuth.createUser({
      email,
      password: generateTempPassword(),
      email_confirm: true,
      user_metadata: {
        role: "COUNSELOR",
        display_name: displayName,
      },
    });

    if (createError) {
      return { error: createError.message };
    }

    revalidatePath("/admin/users");
    return { success: true };
  } catch (error: any) {
    return { error: error.message };
  }
}

export async function createVictimAction(
  _prevState: ManagementActionState | undefined,
  formData: FormData
): Promise<ManagementActionState> {
  try {
    const { userId, role } = await requireRole(["ADMIN", "COUNSELOR"]);

    const email = formData.get("email")?.toString().trim();
    const displayName = formData.get("displayName")?.toString().trim();
    // Counselors are forced to assign to themselves. Admins can optionally pick a counselor later.
    let counselorId = role === "COUNSELOR" ? userId : formData.get("counselorId")?.toString();

    if (!email || !displayName) {
      return { error: "Email and Name are required" };
    }

    const adminClient = createAdminClient();

    // 1. Create the Auth User
    const { data: newUser, error: createError } = await adminClient.auth.admin.createUser({
      email,
      password: generateTempPassword(),
      email_confirm: true,
      user_metadata: {
        role: "VICTIM",
        display_name: displayName,
      },
    });

    if (createError || !newUser.user) {
      return { error: createError?.message || "Failed to create user" };
    }

    // wait for trigger to create profile (handle_new_user trigger in the DB)
    // 2. Create the associated case using the admin client (since RLS might act weird if we are doing this cross-role)
    const { error: caseError } = await adminClient
      .from("cases")
      .insert({
        case_ref: generateCaseRef(),
        status: "OPEN",
        victim_id: newUser.user.id,
        counselor_id: counselorId || null,
      });

    if (caseError) {
      return { error: "User created but failed to spawn case: " + caseError.message };
    }

    if (role === "ADMIN") {
      revalidatePath("/admin/assignments");
    } else {
      revalidatePath("/counselor/cases");
    }

    return { success: true };
  } catch (error: any) {
    return { error: error.message };
  }
}

export async function assignCounselorAction(
  _prevState: ManagementActionState | undefined,
  formData: FormData
): Promise<ManagementActionState> {
  try {
    await requireRole(["ADMIN"]);

    const caseId = formData.get("caseId")?.toString();
    const counselorId = formData.get("counselorId")?.toString() || null;

    if (!caseId) {
      return { error: "Case ID is required" };
    }

    const adminClient = createAdminClient();
    const { error } = await adminClient
      .from("cases")
      .update({ counselor_id: counselorId })
      .eq("id", caseId);

    if (error) {
      return { error: error.message };
    }

    revalidatePath("/admin/assignments");
    return { success: true };
  } catch (error: any) {
    return { error: error.message };
  }
}

"use client";

import { useState } from "react";
import { createCounselorAction } from "@/app/actions/management";
import { Loader2, Plus, AlertCircle, CheckCircle2 } from "lucide-react";

export function CreateCounselorForm() {
  const [isOpen, setIsOpen] = useState(false);
  const [isBusy, setIsBusy] = useState(false);
  const [feedback, setFeedback] = useState<{ text: string; error?: boolean } | null>(null);

  async function handleSubmit(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();
    setIsBusy(true);
    setFeedback(null);

    const formData = new FormData(e.currentTarget);

    try {
      const res = await createCounselorAction(undefined, formData);
      if (res.success) {
        setFeedback({ text: "Counselor successfully created (Default password: Password123!). They can now log in." });
        e.currentTarget.reset();
        setTimeout(() => setIsOpen(false), 4000);
      } else {
        setFeedback({ text: res.error || "Failed to create counselor.", error: true });
      }
    } catch (err: any) {
      setFeedback({ text: err.message || "An unexpected error occurred.", error: true });
    } finally {
      setIsBusy(false);
    }
  }

  if (!isOpen) {
    return (
      <button
        onClick={() => setIsOpen(true)}
        className="inline-flex items-center gap-1.5 rounded-md bg-primary px-3 py-1.5 text-sm font-medium text-primary-foreground hover:bg-primary/90 transition shadow-sm"
      >
        <Plus className="h-4 w-4" />
        New Counselor
      </button>
    );
  }

  return (
    <div className="mb-6 rounded-xl border border-border bg-card p-5 shadow-sm">
      <div className="mb-4 flex items-center justify-between">
        <div>
          <h2 className="text-lg font-semibold text-foreground">Create Counselor Account</h2>
          <p className="text-sm text-muted-foreground">Generate a new verified support access account.</p>
        </div>
        <button
          onClick={() => setIsOpen(false)}
          className="text-sm font-medium text-muted-foreground hover:text-foreground"
        >
          Cancel
        </button>
      </div>

      <form onSubmit={handleSubmit} className="space-y-4 max-w-sm">
        <div>
          <label htmlFor="displayName" className="block text-sm font-medium text-foreground">
            Full Name
          </label>
          <input
            id="displayName"
            name="displayName"
            type="text"
            required
            className="mt-1 block w-full rounded-md border border-input bg-background px-3 py-2 text-sm shadow-sm placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring"
            placeholder="Jane Doe"
          />
        </div>
        <div>
          <label htmlFor="email" className="block text-sm font-medium text-foreground">
            Email Address
          </label>
          <input
            id="email"
            name="email"
            type="email"
            required
            className="mt-1 block w-full rounded-md border border-input bg-background px-3 py-2 text-sm shadow-sm placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring"
            placeholder="jane.doe@sahay.org"
          />
        </div>

        {feedback && (
          <div
            className={`flex items-start gap-2 rounded-md p-3 text-xs ${
              feedback.error ? "bg-destructive/10 text-destructive" : "bg-emerald-50 text-emerald-800"
            }`}
          >
            {feedback.error ? (
              <AlertCircle className="h-4 w-4 shrink-0 mt-0.5" />
            ) : (
              <CheckCircle2 className="h-4 w-4 shrink-0 text-emerald-600 mt-0.5" />
            )}
            <span>{feedback.text}</span>
          </div>
        )}

        <button
          type="submit"
          disabled={isBusy}
          className="inline-flex w-full items-center justify-center gap-2 rounded-md bg-primary px-4 py-2 text-sm font-medium text-primary-foreground shadow transition-colors hover:bg-primary/90 disabled:opacity-50"
        >
          {isBusy && <Loader2 className="h-4 w-4 animate-spin" />}
          {isBusy ? "Creating..." : "Create Account"}
        </button>
      </form>
    </div>
  );
}

